#!/usr/bin/env node
// Regenerates assets/css/icons.css: a self-hosted subset of Font Awesome Free
// 6.4.0 containing only the icons this site's HTML actually uses, as inline
// SVG masks. Replaces the Font Awesome CDN stylesheet + two icon webfonts
// (~360 KB, third-party) with one ~40 KB same-origin file.
//
// Run after adding an icon class (fa-solid / fa-regular / fa-brands fa-NAME)
// to any page:
//   npm i --no-save @fortawesome/fontawesome-free@6.4.0
//   node .github/scripts/build-icons.js
// Markup is unchanged: <i class="fa-solid fa-phone" aria-hidden="true"></i>.
// Icons take the text colour (currentColor) and font-size, as before.
const fs = require("fs");
const path = require("path");
const ROOT = path.resolve(__dirname, "..", "..");
let FA;
try { FA = path.dirname(require.resolve("@fortawesome/fontawesome-free/package.json")); }
catch (e) { FA = path.join(process.env.FA_DIR || "", ""); }
if (!FA || !fs.existsSync(path.join(FA, "svgs"))) {
  console.error("Font Awesome package not found. Run: npm i --no-save @fortawesome/fontawesome-free@6.4.0 (or set FA_DIR)");
  process.exit(1);
}
const files = [ROOT, path.join(ROOT, "_includes")].flatMap((d) =>
  fs.readdirSync(d).filter((f) => f.endsWith(".html")).map((f) => path.join(d, f)));
const used = new Set();
for (const f of files) {
  const re = /fa-(solid|regular|brands) fa-([a-z0-9-]+)/g;
  let m; const s = fs.readFileSync(f, "utf8");
  while ((m = re.exec(s))) used.add(m[1] + " " + m[2]);
}
let css = `/* GENERATED by .github/scripts/build-icons.js -- do not edit by hand.
   Subset of Font Awesome Free 6.4.0 (icons: CC BY 4.0, fontawesome.com). */
.fa-solid,.fa-regular,.fa-brands{display:inline-block;width:1em;height:1em;vertical-align:-0.125em;font-style:normal;line-height:1;background-color:currentColor;-webkit-mask:var(--fa) center/contain no-repeat;mask:var(--fa) center/contain no-repeat}
`;
let n = 0;
for (const key of [...used].sort()) {
  const [style, name] = key.split(" ");
  const file = path.join(FA, "svgs", style, name + ".svg");
  if (!fs.existsSync(file)) { console.error("Unknown icon: " + key); process.exit(1); }
  const svg = fs.readFileSync(file, "utf8").replace(/<!--.*?-->/s, "");
  const vb = svg.match(/viewBox="0 0 (\d+) (\d+)"/);
  const d = svg.match(/ d="([^"]+)"/)[1];
  const uri = `data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 ${vb[1]} ${vb[2]}'%3E%3Cpath d='${d}'/%3E%3C/svg%3E`;
  const w = +vb[1] / +vb[2];
  // Solid and regular variants of one name need different selectors.
  css += `.fa-${style}.fa-${name}{--fa:url("${uri}")${w !== 1 ? `;width:${+w.toFixed(3)}em` : ""}}\n`;
  n++;
}
fs.writeFileSync(path.join(ROOT, "assets", "css", "icons.css"), css);
console.log(`icons.css: ${n} icons, ${(css.length / 1024).toFixed(1)} KB`);
